// Unsplash serves every derivative from the same URL, so one source covers all sizes.
// fm=webp and q=72 keep cards light; crop=entropy centres on the subject.
export function photoUrl(productId, width = 600) {
  const id = PHOTO_IDS[productId];
  if (!id) return null;
  return `https://images.unsplash.com/${id}?auto=format&fit=crop&crop=entropy&w=${width}&h=${width}&q=72&fm=webp`;
}

export function photoSrcSet(productId) {
  const id = PHOTO_IDS[productId];
  if (!id) return null;
  return [300, 600, 900].map((w) => `${photoUrl(productId, w)} ${w}w`).join(', ');
}
